import java.util.*;

class KthLargest {
    private final int k;
    private final PriorityQueue<Integer> heap = new PriorityQueue<>();

    public KthLargest(int k, int[] nums) {
        this.k = k;
        for (int num : nums) {
            add(num);
        }
    }

    public int add(int val) {
        heap.offer(val);
        if (heap.size() > k) {
            heap.poll();
        }
        return heap.peek();
    }
}

import java.util.*;

class KthLargest {
    private final int k;
    private final List<Integer> values = new ArrayList<>();

    public KthLargest(int k, int[] nums) {
        this.k = k;
        for (int num : nums) {
            insertSorted(num);
        }
    }

    public int add(int val) {
        insertSorted(val);
        return values.get(values.size() - k);
    }

    private void insertSorted(int val) {
        int index = Collections.binarySearch(values, val);
        if (index < 0) {
            index = -index - 1;
        }
        values.add(index, val);
    }
}

import java.util.*;

class KthLargest {
    private final int k;
    private final TreeMap<Integer, Integer> counts = new TreeMap<>();

    public KthLargest(int k, int[] nums) {
        this.k = k;
        for (int num : nums) {
            insert(num);
        }
    }

    public int add(int val) {
        insert(val);
        int remaining = k;
        for (Map.Entry<Integer, Integer> entry : counts.descendingMap().entrySet()) {
            remaining -= entry.getValue();
            if (remaining <= 0) {
                return entry.getKey();
            }
        }
        throw new IllegalStateException("not enough values");
    }

    private void insert(int val) {
        counts.put(val, counts.getOrDefault(val, 0) + 1);
    }
}

import java.util.*;

class KthLargest {
    private final int k;
    private final List<Integer> values = new ArrayList<>();

    public KthLargest(int k, int[] nums) {
        this.k = k;
        for (int num : nums) {
            values.add(num);
        }
    }

    public int add(int val) {
        values.add(val);
        int[] copy = new int[values.size()];
        for (int i = 0; i < values.size(); i++) {
            copy[i] = values.get(i);
        }
        int target = values.size() - k;
        return quickselect(copy, target);
    }

    private int quickselect(int[] nums, int target) {
        int left = 0;
        int right = nums.length - 1;
        while (left <= right) {
            int pivotIndex = partition(nums, left, right);
            if (pivotIndex == target) {
                return nums[pivotIndex];
            }
            if (pivotIndex < target) {
                left = pivotIndex + 1;
            } else {
                right = pivotIndex - 1;
            }
        }
        return nums[target];
    }

    private int partition(int[] nums, int left, int right) {
        int pivot = nums[right];
        int store = left;
        for (int i = left; i < right; i++) {
            if (nums[i] <= pivot) {
                swap(nums, store, i);
                store++;
            }
        }
        swap(nums, store, right);
        return store;
    }

    private void swap(int[] nums, int i, int j) {
        int temp = nums[i];
        nums[i] = nums[j];
        nums[j] = temp;
    }
}
